from django.utils.text import slugify


def _unique_slug(Product, value):
    base_slug = slugify(value)[:220] or 'product'
    slug = base_slug
    counter = 2
    while Product.objects.filter(slug=slug).exists():
        suffix = f'-{counter}'
        slug = f'{base_slug[:255 - len(suffix)]}{suffix}'
        counter += 1
    return slug


def _field_value(value):
    return str(value) if value else ''


def _infer_group(product):
    text = f'{product.title} {product.name}'.lower()
    if any(word in text for word in ['busy', 'zoho', 'quickbook', 'marg', 'account']):
        return 'accounting-software'
    if any(word in text for word in ['erp', 'sap']):
        return 'erp-software'
    return 'tally-prime'


